describe('Payment Flow', () => {
    beforeEach(() => {
        cy.visit('/checkout');
    });

    it('should complete a purchase successfully with valid card details', () => {
        cy.get('input[name="cardNumber"]').type('4111111111111111');
        cy.get('input[name="expiryDate"]').type('12/25');
        cy.get('input[name="cvv"]').type('123');
        cy.get('button[type="submit"]').click();

        cy.url().should('include', '/confirmation');
        cy.get('.confirmation-message').should('contain', 'Thank you for your purchase!');
    });

    it('should show an error message for invalid card details', () => {
        cy.get('input[name="cardNumber"]').type('1234567812345678');
        cy.get('input[name="expiryDate"]').type('12/25');
        cy.get('input[name="cvv"]').type('123');
        cy.get('button[type="submit"]').click();

        cy.get('.error-message').should('be.visible').and('contain', 'Invalid card details');
    });
});
